// ─── File: GenerationDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.gen;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class GenerationDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Long-lived: loaded ONCE, referenced all day → promoted to OLD gen.
        FraudModel model = new FraudModel("v2026.10");

        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        FraudScorer scorer = new FraudScorer(model);

        // Short-lived: each score creates temporary objects → YOUNG gen churn.
        long temp = 0;
        temp += scorer.scoreMany(rajesh, 50_000);
        temp += scorer.scoreMany(priya, 50_000);

        final long tempObjects = temp;
        log.info(() -> "Short-lived ScoreResult objects (young gen): " + tempObjects);
        log.info(() -> "Long-lived model still loaded (old gen): " + model.getVersion());
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private final BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in FraudModel.java (LONG-LIVED → Old gen) ───
class FraudModel {
    private final String version;
    FraudModel(String version) { this.version = version; }
    // A real model would hold large weights; here version stands in.
    double weightFor(BigDecimal amount) { return amount.doubleValue() > 100000 ? 0.8 : 0.2; }
    String getVersion() { return version; }
}

// ─── Would be in ScoreResult.java (SHORT-LIVED → Young gen) ───
class ScoreResult {
    private final double score;
    ScoreResult(double score) { this.score = score; }
    boolean suspicious() { return score > 0.5; }
}

// ─── Would be in FraudScorer.java ───
class FraudScorer {
    private final FraudModel model;         // reference to the long-lived model
    FraudScorer(FraudModel model) { this.model = model; }

    long scoreMany(Account account, int times) {
        long suspiciousCount = 0;
        for (int i = 0; i < times; i++) {
            // New ScoreResult every iteration → born in Eden, dies immediately.
            ScoreResult result = new ScoreResult(model.weightFor(account.getBalance()));
            if (result.suspicious()) suspiciousCount++;
        }
        return suspiciousCount; // ScoreResult objects are now young garbage
    }
}
